export default function JapanMap({ selectedArea, onAreaChange, onPrefectureChange }: JapanMapProps) {
  const handleRegionClick = (regionId: string) => {
    if (selectedArea === regionId) {
      onAreaChange('');
      onPrefectureChange('');
    } else {
      onAreaChange(regionId);
      onPrefectureChange('');
    }
  };

  const getShopCount = (regionId: string) => {
    const area = shopAreas.find((a) => a.id === regionId);
    return area ? area.count : 0;
  };

  return (
    <div className="bg-white border border-gray-200 rounded-xl p-5">
      <h3 className="font-bold text-gray-900 mb-3 flex items-center gap-2 text-sm">
        <i className="ri-map-pin-2-line text-red-500 w-5 h-5 flex items-center justify-center"></i>
        地図からエリアを選択
      </h3>
      <div className="relative w-full" style={{ aspectRatio: '4 / 3' }}>
        <svg
          viewBox="120 50 520 620"
          className="w-full h-full"
          xmlns="http://www.w3.org/2000/svg"
        >
          {Object.entries(regionPaths).map(([id, region]) => {
            const isSelected = selectedArea === id;
            return (
              <g key={id} className="cursor-pointer" onClick={() => handleRegionClick(id)}>
                <path
                  d={region.d}
                  fill={isSelected ? '#dc2626' : '#fef2f2'}
                  stroke={isSelected ? '#991b1b' : '#e5e7eb'}
                  strokeWidth={isSelected ? 2.5 : 1.5}
                  className="transition-all duration-200 hover:fill-red-200"
                  style={isSelected ? {} : undefined}
                />
                <text
                  x={region.labelX}
                  y={region.labelY - 8}
                  textAnchor="middle"
                  className="pointer-events-none select-none"
                  fill={isSelected ? '#ffffff' : '#374151'}
                  fontSize="14"
                  fontWeight="700"
                >
                  {region.label}
                </text>
                <text
                  x={region.labelX}
                  y={region.labelY + 12}
                  textAnchor="middle"
                  className="pointer-events-none select-none"
                  fill={isSelected ? '#fecaca' : '#6b7280'}
                  fontSize="11"
                  fontWeight="500"
                >
                  {getShopCount(id)}店舗
                </text>
              </g>
            );
          })}
        </svg>
      </div>
      {selectedArea && (
        <div className="mt-3 flex items-center justify-center gap-2 text-xs text-red-600 font-medium">
          <i className="ri-checkbox-circle-fill w-4 h-4 flex items-center justify-center"></i>
          {shopAreas.find((a) => a.id === selectedArea)?.name}エリアを選択中
        </div>
      )}
    </div>
  );
}
